using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Stops the preliminary uploading of a file. Supported only for files uploaded by using preliminaryUploadFile
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> CancelPreliminaryUploadFileAsync(int fileId = default)
    {

           using var activity =  StartCallActivity("CancelPreliminaryUploadFileAsync", typeof(CancelPreliminaryUploadFile).FullName ?? "CancelPreliminaryUploadFileAsync");

           try
           {
             return client.CancelPreliminaryUploadFileAsync(fileId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
